from rest_framework.generics import RetrieveAPIView
from rest_framework import permissions
from .models import CustomAPIToken
from .serializers import CustomAPITokenSerializer

class TokenDetailInspectView(RetrieveAPIView):
    serializer_class = CustomAPITokenSerializer
    permission_classes = [permissions.IsAuthenticated]
    lookup_field = 'key'

    def get_queryset(self):
        return CustomAPIToken.objects.filter(user=self.request.user)
